<script setup lang="ts">
import { computed, reactive, ref } from 'vue'; import { useMutation,useQuery,useQueryClient } from '@tanstack/vue-query'; import { ElDialog,ElMessage,ElMessageBox } from 'element-plus'; import { useRoute } from 'vue-router'
import { worldbookApi } from '@/api/endpoints/assets'; import type { ReconstructionCandidate,WorldbookEntryResponse,WorldbookScope,WorldbookVisibility } from '@/api/types'; import EmptyState from '@/components/base/EmptyState.vue'; import ErrorState from '@/components/base/ErrorState.vue'; import LoadingState from '@/components/base/LoadingState.vue'; import ProblemAlert from '@/components/base/ProblemAlert.vue'; import ReconstructionCandidatePanel from '@/components/reconstruction/ReconstructionCandidatePanel.vue'; import { queryKeys } from '@/queries/keys'
const route=useRoute(),client=useQueryClient(),projectId=computed(()=>String(route.params.projectId??'')); const query=useQuery({queryKey:computed(()=>queryKeys.worldbook(projectId.value)),queryFn:()=>worldbookApi.list(projectId.value)}); const open=ref(false),editing=ref<WorldbookEntryResponse>(); const form=reactive({title:'',content:'',active:true,constantEnabled:false,vectorEnabled:false,keywords:'',priority:100,scopeType:'PROJECT' as WorldbookScope,scopeRefId:'',visibilityType:'ALL' as WorldbookVisibility,visibilityRefId:''})
const mutation=useMutation({mutationFn:()=>{const body={title:form.title.trim(),content:form.content,active:form.active,constantEnabled:form.constantEnabled,vectorEnabled:form.vectorEnabled,keywords:form.keywords.split(',').map(v=>v.trim()).filter(Boolean),priority:Number(form.priority),scopeType:form.scopeType,scopeRefId:form.scopeRefId.trim()||null,visibilityType:form.visibilityType,visibilityRefId:form.visibilityRefId.trim()||null}; return editing.value?worldbookApi.update(editing.value.id,{...body,expectedVersion:editing.value.version}):worldbookApi.create(projectId.value,body)},onSuccess:async()=>{await client.invalidateQueries({queryKey:queryKeys.worldbook(projectId.value)});open.value=false;ElMessage.success('世界书条目已保存')}})
const cancelMutation=useMutation({mutationFn:(id:string)=>worldbookApi.cancel(id),onSuccess:async()=>{await Promise.all([client.invalidateQueries({queryKey:queryKeys.worldbook(projectId.value)}),client.invalidateQueries({queryKey:['reconstruction-module-candidates',projectId.value,'WORLDBOOK']}),client.invalidateQueries({queryKey:['book-reconstruction',projectId.value]})]);ElMessage.success('世界书应用已取消，相关候选已恢复')},onError:()=>ElMessage.error('取消世界书应用失败')})
function show(x?:WorldbookEntryResponse){editing.value=x;Object.assign(form,x?{title:x.title,content:x.content,active:x.active,constantEnabled:x.constantEnabled,vectorEnabled:x.vectorEnabled,keywords:x.keywords.join(', '),priority:x.priority,scopeType:x.scopeType,scopeRefId:x.scopeRefId??'',visibilityType:x.visibilityType,visibilityRefId:x.visibilityRefId??''}:{title:'',content:'',active:true,constantEnabled:false,vectorEnabled:false,keywords:'',priority:100,scopeType:'PROJECT',scopeRefId:'',visibilityType:'ALL',visibilityRefId:''});open.value=true} async function save(){try{await mutation.mutateAsync()}catch{/*rendered*/}}
function useCandidate(candidate:ReconstructionCandidate){show();form.title=candidate.content.split(/[，。；：]/,1)[0]!.slice(0,80);form.content=candidate.content;form.keywords=form.title}
async function cancelEntry(entry:WorldbookEntryResponse){const confirmed=await ElMessageBox.confirm(entry.title==='TXT AI 重建 · 世界设定'?'取消该自动世界书会让其中所有关联事实恢复为待审核，是否继续？':'取消该世界书条目并让关联候选恢复为待审核？','取消世界书应用',{confirmButtonText:'确认取消',cancelButtonText:'返回',type:'warning'}).then(()=>true).catch(()=>false);if(confirmed)cancelMutation.mutate(entry.id)}
</script>
<template><main class="page-container"><header class="page-header"><div><p class="eyebrow">Worldbook</p><h1 tabindex="-1">世界书</h1><p>TXT 全项目重建会自动归并可信世界事实；仍可手动维护条目内容和激活配置。</p></div><button class="sw-button sw-button--primary" @click="show()">新建条目</button></header><div class="capability-note">激活调试器、世界树拖动和历史接口尚未由后端提供，本阶段不伪造。</div><ReconstructionCandidatePanel :project-id="projectId" candidate-type="WORLDBOOK" title="AI 世界书拆书记录" description="原文明示且无歧义的事实会自动合并到正式世界书；已写入正式世界书的候选不再重复显示，不确定或冲突内容继续留在这里审核。" use-label="载入世界书表单" @use="useCandidate"/><LoadingState v-if="query.isPending.value"/><ErrorState v-else-if="query.isError.value" :error="query.error.value" @retry="query.refetch()"/><EmptyState v-else-if="!query.data.value?.length" title="正式世界书为空" description="完成 TXT 全项目重建后，可信世界事实会自动写入；也可手动创建条目。"><button class="sw-button sw-button--primary" @click="show()">创建条目</button></EmptyState><section v-else class="asset-grid"><article v-for="x in query.data.value" :key="x.id" class="asset-card"><div class="asset-card-heading"><div><span class="asset-type">优先级 {{ x.priority }}</span><h2>{{ x.title }}</h2></div><span class="status-pill">{{ x.active?'启用':'停用' }}</span></div><p>{{ x.content }}</p><div class="keyword-list"><span v-for="k in x.keywords" :key="k">{{ k }}</span></div><div class="asset-actions"><button @click="show(x)">编辑配置</button><button :disabled="cancelMutation.isPending.value" @click="cancelEntry(x)">取消</button></div></article></section>
<ElDialog v-model="open" :title="editing?'编辑世界书':'新建世界书'" width="min(720px,94vw)"><ProblemAlert v-if="mutation.isError.value" :error="mutation.error.value"/><form id="worldbook-form" class="sw-form two-column-form" @submit.prevent="save"><label class="form-field form-field--full"><span>标题</span><input v-model="form.title" maxlength="200" required/></label><label class="form-field form-field--full"><span>内容</span><textarea v-model="form.content" rows="8" maxlength="200000" required/></label><label class="form-field form-field--full"><span>关键词（逗号分隔）</span><input v-model="form.keywords"/></label><label class="form-field"><span>优先级</span><input v-model.number="form.priority" type="number" min="0" max="1000"/></label><label class="form-field"><span>作用域</span><select v-model="form.scopeType"><option>PROJECT</option><option>CHAPTER</option><option>CHARACTER</option></select></label><label v-if="form.scopeType!=='PROJECT'" class="form-field"><span>作用域资源 UUID</span><input v-model="form.scopeRefId" required/></label><label class="form-field"><span>可见性</span><select v-model="form.visibilityType"><option>ALL</option><option>AUTHOR_ONLY</option><option>CHARACTER_ONLY</option></select></label><label v-if="form.visibilityType==='CHARACTER_ONLY'" class="form-field"><span>可见人物 UUID</span><input v-model="form.visibilityRefId" required/></label><label class="check-field"><input v-model="form.active" type="checkbox"/>启用</label><label class="check-field"><input v-model="form.constantEnabled" type="checkbox"/>常驻激活</label><label class="check-field"><input v-model="form.vectorEnabled" type="checkbox"/>向量激活</label></form><template #footer><button class="sw-button sw-button--secondary" @click="open=false">取消</button><button class="sw-button sw-button--primary" form="worldbook-form">保存</button></template></ElDialog></main></template>
